import { readFile, writeFile, mkdir, rename, rm } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { randomUUID } from 'node:crypto';

const DEFAULT_REGION = 'eu-north-7';
const DEFAULT_RETRY = { maxAttempts: 5, backoffMs: 125 };

function parseConfig(text) {
  const config = JSON.parse(text);
  if (!config || typeof config !== 'object' || Array.isArray(config)) {
    throw new TypeError('Config must be a JSON object');
  }
  if (config.version !== 1 && config.version !== 3) {
    throw new Error(`Unsupported config version: ${config.version}`);
  }
  return config;
}

function migrate(config, options) {
  let result;
  if (config.version === 3) {
    result = { ...config };
  } else {
    const known = new Set(['version', 'name', 'timeoutSeconds', 'flags', 'region', 'retry', 'legacy']);
    const legacy = { ...config.legacy };
    for (const [key, value] of Object.entries(config)) {
      if (!known.has(key)) {
        Object.defineProperty(legacy, key, { value, enumerable: true, writable: true, configurable: true });
      }
    }
    result = {
      version: 3,
      ...(Object.hasOwn(config, 'name') ? { name: config.name } : {}),
      ...(Object.hasOwn(config, 'timeoutSeconds') ? { timeoutMs: config.timeoutSeconds * 1000 } : {}),
      features: Object.keys(config.flags ?? {}).filter(key => config.flags[key] === true).sort(),
      region: config.region ?? DEFAULT_REGION,
      retry: { ...DEFAULT_RETRY, ...config.retry },
      ...(Object.keys(legacy).length || Object.hasOwn(config, 'legacy') ? { legacy } : {}),
    };
  }
  if (options.region !== undefined) result.region = options.region;
  return result;
}

export async function migrateFile(inputPath, outputPath, options = {}) {
  const directory = dirname(resolve(outputPath));
  const backupPath = join(directory, 'backups', 'source.json');
  const source = await readFile(inputPath);
  let config;
  try {
    config = parseConfig(source.toString('utf8'));
  } catch (error) {
    // Only truncated JSON qualifies for the approved recovery procedure.
    if (!(error instanceof SyntaxError) || !/unexpected end|unterminated/i.test(error.message)) throw error;
    config = parseConfig(await readFile(backupPath, 'utf8'));
    const recoveryPath = join(directory, 'recovery', 'source.bad.json');
    if (resolve(inputPath) === backupPath) throw new Error('Cannot recover a corrupt backup from itself');
    await mkdir(dirname(recoveryPath), { recursive: true });
    // Exclusive creation avoids replacing evidence from an earlier recovery.
    await writeFile(recoveryPath, source, { flag: 'wx' });
    await rm(inputPath);
  }
  const result = migrate(config, options);
  await mkdir(dirname(backupPath), { recursive: true });
  try {
    await writeFile(backupPath, source, { flag: 'wx' });
  } catch (error) {
    if (error.code !== 'EEXIST') throw error;
  }
  const temporaryPath = join(directory, `.migration-${randomUUID()}.tmp`);
  try {
    await writeFile(temporaryPath, `${JSON.stringify(result, null, 2)}\n`, { flag: 'wx' });
    await rename(temporaryPath, outputPath);
  } finally {
    await rm(temporaryPath, { force: true });
  }
  return result;
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, mkdir, writeFile, readFile, rm } from 'node:fs/promises';
import { join } from 'node:path';
import { migrateFile } from '../src/migrate.mjs';

async function workspace(run) {
  const directory = await mkdtemp(join(process.cwd(), '.policy-'));
  try { await run(directory); } finally { await rm(directory, { recursive: true, force: true }); }
}

test('defaults, customer data, exact backup, and invocation-only override', () => workspace(async d => {
  const input = join(d, 'input.json');
  const output = join(d, 'output.json');
  const source = '{ "version":1,"name":"customer","timeoutSeconds":2,"custom":{"keep":true}}\n';
  await writeFile(input, source);
  const result = await migrateFile(input, output, { region: 'temporary' });
  assert.equal(result.region, 'temporary');
  assert.deepEqual(result.retry, { maxAttempts: 5, backoffMs: 125 });
  assert.deepEqual(result.legacy, { custom: { keep: true } });
  assert.equal(await readFile(join(d, 'backups/source.json'), 'utf8'), source);
  assert.equal((await migrateFile(input, output)).region, 'eu-north-7');
}));

test('v3 remains semantically unchanged', () => workspace(async d => {
  const config = { version: 3, region: 'original', retry: { maxAttempts: 2 }, custom: [1, 2] };
  const input = join(d, 'input.json');
  await writeFile(input, JSON.stringify(config));
  assert.deepEqual(await migrateFile(input, join(d, 'out.json')), config);
  assert.deepEqual(await migrateFile(input, join(d, 'out.json'), { region: 'override' }), { ...config, region: 'override' });
}));

test('truncated source is recovered without changing backup', () => workspace(async d => {
  await mkdir(join(d, 'backups'));
  const backup = '{"version":1,"custom":{"keep":true}}\n';
  const corrupt = '{"version":';
  const input = join(d, 'input.json');
  await writeFile(join(d, 'backups/source.json'), backup);
  await writeFile(input, corrupt);
  const result = await migrateFile(input, join(d, 'output.json'));
  assert.deepEqual(result.legacy, { custom: { keep: true } });
  assert.equal(await readFile(join(d, 'backups/source.json'), 'utf8'), backup);
  assert.equal(await readFile(join(d, 'recovery/source.bad.json'), 'utf8'), corrupt);
  await assert.rejects(readFile(input), { code: 'ENOENT' });
}));

#!/usr/bin/env node
// Usage: node bin/migrate.mjs INPUT OUTPUT [REGION_OVERRIDE]
import { migrateFile } from '../src/migrate.mjs';

const args = process.argv.slice(2);
if (args.length < 2 || args.length > 3) {
  console.error('Usage: node bin/migrate.mjs INPUT OUTPUT [REGION_OVERRIDE]');
  process.exitCode = 1;
} else {
  try {
    const [input, output, region] = args;
    const result = await migrateFile(input, output, region === undefined ? {} : { region });
    console.log(JSON.stringify(result, null, 2));
  } catch (error) {
    console.error(`Migration failed: ${error.message}`);
    process.exitCode = 1;
  }
}

